 Q(106, "Majority Element", "hard", "Find the value that appears more than n/2 times.", "Use the Boyer-Moore voting algorithm.", "public class Majority {\n    public static void main(String[] args) {\n        int[] arr = {3, 2, 3};\n        int cand = 0, count = 0;\n        for (int v : arr) {\n            if (count == 0) cand = v;\n            count += (v == cand) ? 1 : -1;\n        }\n        System.out.println(cand);\n    }\n}", ["arrays", "majority", "voting"], "Cancel out pairs of different values."),
 Q(107, "Best Time to Buy and Sell Stock", "hard", "Maximize profit by buying low and selling high once.", "Track the minimum price and maximum profit.", "public class Stock {\n    public static void main(String[] args) {\n        int[] prices = {7, 1, 5, 3, 6, 4};\n        int min = prices[0], profit = 0;\n        for (int p : prices) {\n            min = Math.min(min, p);\n            profit = Math.max(profit, p - min);\n        }\n        System.out.println(profit);\n    }\n}", ["arrays", "greedy", "stock"], "Update the minimum seen so far each day."),
