 Q(109, "Product of Array Except Self", "hard", "Return an array where each element is the product of all others.", "Compute prefix and suffix products without division.", "public class Product {\n    public static void main(String[] args) {\n        int[] nums = {1, 2, 3, 4};\n        int n = nums.length;\n        int[] res = new int[n];\n        res[0] = 1;\n        for (int i = 1; i < n; i++) res[i] = res[i - 1] * nums[i - 1];\n        int right = 1;\n        for (int i = n - 1; i >= 0; i--) {\n            res[i] *= right;\n            right *= nums[i];\n        }\n        System.out.println(java.util.Arrays.toString(res));\n    }\n}", ["arrays", "prefix", "suffix"], "Use two passes to avoid division."),
 Q(110, "Search in Rotated Sorted Array", "hard", "Find a target value in an array that was rotated around a pivot.", "Use modified binary search.", "public class RotatedSearch {\n    public static void main(String[] args) {\n        int[] nums = {4, 5, 6, 7, 0, 1, 2};\n        int target = 0, l = 0, r = nums.length - 1;\n        while (l <= r) {\n            int m = l + (r - l) / 2;\n            if (nums[m] == target) { System.out.println(m); break; }\n            if (nums[l] <= nums[m]) {\n                if (target >= nums[l] && target < nums[m]) r = m - 1;\n                else l = m + 1;\n            } else {\n                if (target > nums[m] && target <= nums[r]) l = m + 1;\n                else r = m - 1;\n            }\n        }\n    }\n}", ["arrays", "binary search", "rotated"], "Check which half is sorted first.")
